/**
 * Gold screen: agent console (an agent that writes emails to customers; a person approves each one).
 * Why it is built this way:
 * - The plan is visible before and during the work: StepTimeline shows what is done, what is waiting and what is next.
 * - Nothing that cannot be undone happens without a yes: ApprovalPrompt states exactly what will be sent, to whom,
 *   with equal Approve and Deny. Amber appears only here, because only here a person has to act.
 * - The draft says it was written by the AI (AILabel), and why the agent wrote it.
 * - Every decision lands in ActionLog: who approved it, when, and whether it can be undone. Sent email cannot.
 * - On a phone the plan stacks above the draft; nothing is hidden behind hover.
 */
import { useState } from "react";
import { ActionLog, AILabel, ApprovalPrompt, AppShell, Callout, StepTimeline } from "@tattva/ui";

type Draft = { id: string; to: string; email: string; subject: string; body: string; why: string };
const drafts: Draft[] = [
  { id: "dana", to: "Dana Okafor", email: "dana@brightpath.example", subject: "Your invoice #1042 is ready", body: "Hi Dana,\n\nYour invoice for March is ready. The total is $480, due on 15 April.\n\nBest,\nThe team", why: "Dana's invoice was issued this morning and she has not been told yet." },
  { id: "marcus", to: "Marcus Lee", email: "marcus@lee.example", subject: "Your order has shipped", body: "Hi Marcus,\n\nYour order left our warehouse today and should arrive on Friday.\n\nBest,\nThe team", why: "The courier confirmed pickup at 9:12." },
];

export function App() {
  const [i, setI] = useState(0);
  const [log, setLog] = useState<{ id: string; action: string; actor: string; status: "done" | "failed" | "waiting"; time: string; approvedBy?: "you"; notUndoableReason?: string }[]>([]);
  const d = drafts[i];
  const decide = (yes: boolean) => {
    setLog((l) => [{ id: d.id, action: `${yes ? "Sent" : "Held back"} "${d.subject}" to ${d.to}`, actor: "Email agent", status: yes ? "done" : "failed", time: "Just now", approvedBy: "you", notUndoableReason: yes ? "The email was already sent." : undefined }, ...l]);
    setI((n) => n + 1);
  };
  const steps = drafts.map((x, n) => ({ id: x.id, title: `Email to ${x.to}`, detail: n < i ? "Decided" : n === i ? "Waiting for your approval" : "Not written yet", state: (n < i ? "done" : n === i ? "active" : "todo") as "done" | "active" | "todo" }));

  return (
    <AppShell>
      <div className="mx-auto grid w-full max-w-5xl gap-6 p-4 md:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)] md:p-8">
        <section aria-labelledby="plan" className="grid content-start gap-4">
          <h1 id="plan" className="m-0 text-lead leading-6 font-semibold">Customer emails</h1>
          <p className="m-0 text-body leading-6 text-fg-muted">The agent writes each email. Nothing is sent until you say yes.</p>
          <StepTimeline steps={steps} />
          {log.length > 0 && <ActionLog items={log} />}
        </section>
        <section aria-label="Current draft" className="grid content-start gap-4">
          {d ? (
            <>
              <div className="rounded-card border border-line bg-surface p-4">
                <div className="flex items-start justify-between gap-3">
                  <p className="m-0 text-body leading-6"><span className="text-fg-muted">To:</span> {d.to} ({d.email})<br /><span className="text-fg-muted">Subject:</span> <strong>{d.subject}</strong></p>
                  <AILabel level="message" />
                </div>
                <p className="m-0 mt-3 whitespace-pre-line text-body leading-6">{d.body}</p>
                <p className="m-0 mt-3 text-small leading-5 text-fg-muted">Why the agent wrote this: {d.why}</p>
              </div>
              <ApprovalPrompt risk="medium" action={`Send this email to ${d.to}`}
                detail={<>This sends “{d.subject}” to <strong>{d.email}</strong>. A sent email cannot be taken back.</>}
                onApprove={() => decide(true)} onDeny={() => decide(false)} />
            </>
          ) : (
            <Callout tone="success" title="All emails decided">The agent has nothing else waiting for you.</Callout>
          )}
        </section>
      </div>
    </AppShell>
  );
}

/**
 * Gold screen: chat assistant (a hotel finder).
 * Why it is built this way:
 * - The first screen is never empty: EmptyState says what the assistant can do, with three starters.
 * - Answers that recommend things are cards, not paragraphs: CardRow of ResultCards with the same facts each,
 *   so people compare like with like. On a phone the row swipes and the next card peeks in.
 * - Every fact that came from somewhere has a numbered CitationMarker and a SourceList under the answer.
 * - The assistant says it is an AI once, quietly (AIDisclosure in the footnote), not on every message.
 * - Feedback sits under the answer, after the person has read it. Book is the only action on a card.
 * - Sample data is labelled as sample until a real model and hotel data are connected.
 */
import { useState } from "react";
import {
  AIDisclosure, CardRow, CitationMarker, Composer, EmptyState, FeedbackBar, Message, MessageList,
  ResultCard, SourceList, SuggestionChips, ThreadTemplate, TypingIndicator,
} from "@tattva/ui";

const hotels = [
  { id: "arts", title: "Hôtel des Arts", subtitle: "Montmartre, Paris", rating: "4.6 of 5", walk: "4 min", price: 182, tag: "Free cancellation" },
  { id: "marais", title: "Le Petit Marais", subtitle: "Le Marais, Paris", rating: "4.4 of 5", walk: "2 min", price: 214 },
  { id: "rive", title: "Rive Gauche Studio", subtitle: "Saint-Germain, Paris", rating: "4.8 of 5", walk: "6 min", price: 249, tag: "Best match" },
];
const sources = [
  { id: 1, title: "Hôtel des Arts: rooms and prices", url: "https://example.com/arts", domain: "example.com", snippet: "Sample data: doubles from €182 a night." },
  { id: 2, title: "Paris metro map", url: "https://example.com/metro", domain: "example.com" },
];
const starters = ["A quiet hotel in Paris under €250", "Near the metro, with breakfast", "Somewhere good for a family"];

type Turn = { role: "user" | "assistant"; text: string };

export function App() {
  const [turns, setTurns] = useState<Turn[]>([]);
  const [busy, setBusy] = useState(false);
  const ask = (text: string) => {
    setTurns((t) => [...t, { role: "user", text }]);
    setBusy(true);
    setTimeout(() => { setTurns((t) => [...t, { role: "assistant", text }]); setBusy(false); }, 900); // stand-in for a real model
  };

  return (
    <ThreadTemplate
      header={<span className="text-body leading-5 font-semibold">Hotel finder</span>}
      footnote={<AIDisclosure>Answers are written by an AI and use sample data. Check prices before you book.</AIDisclosure>}
      composer={<Composer onSend={ask} generating={busy} onStop={() => setBusy(false)} placeholder="Where, when and your budget…" />}
    >
      {turns.length === 0 ? (
        <EmptyState variant="first-use" title="Find a hotel that fits" action={<SuggestionChips suggestions={starters} onPick={ask} />}>
          Say where, when and what matters to you. I will compare a few hotels and show where each fact came from.
        </EmptyState>
      ) : (
        <MessageList label="Conversation">
          {turns.map((t, i) => t.role === "user"
            ? <Message key={i} role="user">{t.text}</Message>
            : (
              <Message key={i} role="assistant" footer={<FeedbackBar onSubmit={() => {}} />}>
                <p className="m-0">Three hotels fit, from €182 a night<CitationMarker n={1} href="#source-1" />. All are a short walk from the metro<CitationMarker n={2} href="#source-2" />.</p>
                <div className="mt-3">
                  <CardRow label="Hotels that fit">
                    {hotels.map((h) => (
                      <ResultCard key={h.id} title={h.title} subtitle={h.subtitle} tag={h.tag ? { label: h.tag } : undefined}
                        facts={[{ label: "Rating", value: h.rating }, { label: "Walk to metro", value: h.walk }]}
                        price={{ value: h.price, currency: "EUR", locale: "en-GB", note: "a night" }}
                        action={{ label: "Book", onClick: () => {} }} />
                    ))}
                  </CardRow>
                </div>
                <div className="mt-3"><SourceList sources={sources} /></div>
              </Message>
            ))}
          {busy && <TypingIndicator label="Looking for hotels" />}
        </MessageList>
      )}
    </ThreadTemplate>
  );
}

/**
 * Gold screen: creative tool (pictures from text for a bakery's posts).
 * Why it is built this way:
 * - One prompt box with real examples, and settings people understand (shape, look), each with its cost shown
 *   before Generate, so nobody is surprised by what a run spends.
 * - Progress is honest: GenerationProgress says what is happening and can be cancelled.
 * - Several variations side by side (VariantGrid), one chosen at a time, marked as AI-made (AILabel).
 * - Nothing is lost: earlier results stay one tap away.
 */
import { useState } from "react";
import { AILabel, GenerationProgress, ParameterPanel, PromptBox, VariantGrid, type ParameterSpec } from "@tattva/ui";

const params: ParameterSpec[] = [
  { kind: "aspect", id: "shape", label: "Post shape", options: [{ value: "1:1", label: "1:1" }, { value: "4:5", label: "4:5" }, { value: "9:16", label: "9:16" }] },
  { kind: "segmented", id: "look", label: "Look", options: [{ value: "warm", label: "Warm" }, { value: "bright", label: "Bright" }, { value: "moody", label: "Moody" }] },
];
const tones = ["bg-[var(--pastel-rose)]", "bg-[var(--pastel-mint)]", "bg-[var(--pastel-sky)]", "bg-[var(--pastel-lilac)]"];

export function App() {
  const [values, setValues] = useState<Record<string, string | number | boolean | null>>({ shape: "1:1", look: "warm" });
  const [state, setState] = useState<"idle" | "generating" | "done">("idle");
  const [sel, setSel] = useState("v1");
  const run = () => { setState("generating"); setTimeout(() => setState("done"), 1200); }; // stand-in for a real model

  return (
    <main className="mx-auto grid w-full max-w-5xl gap-6 p-4 md:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)] md:p-8">
      <section aria-labelledby="t" className="grid content-start gap-4">
        <h1 id="t" className="m-0 text-lead leading-6 font-semibold">Pictures for your posts</h1>
        <PromptBox onGenerate={run} busy={state === "generating"} placeholder="Describe the picture…"
          examples={["Strawberry cupcakes on a marble counter", "A loaf of sourdough in morning light"]} />
        {state === "generating" && <GenerationProgress status="generating" percent={40} eta="About 10 seconds left" onCancel={() => setState("idle")} />}
        {state === "done" && (
          <>
            <div className="flex items-center justify-between gap-3"><h2 className="m-0 text-body leading-5 font-semibold">Four versions</h2><AILabel level="image" /></div>
            <VariantGrid selectedId={sel} onSelect={setSel}
              variants={tones.map((t, n) => ({ id: `v${n + 1}`, label: `Version ${n + 1}`, node: <div className={`size-full ${t}`} /> }))} />
          </>
        )}
      </section>
      <ParameterPanel title="Settings" parameters={params} values={values} onChange={setValues} onGenerate={run}
        busy={state === "generating"} estimateCost={() => 4} formatCost={(c) => `${c} credits`} />
    </main>
  );
}

/**
 * Gold screen: generative UI (the assistant asks what it needs, then answers in parts).
 * Why it is built this way:
 * - When the request is unclear, the assistant asks instead of guessing: QuestionSet, one question at a time,
 *   with a recommended option, You decide, Use the defaults and a last look before sending.
 * - The answer arrives in Sections that open as they stream, so a long answer stays readable.
 * - After answering, the questions shrink to a Receipt so the thread stays short.
 */
import { useState } from "react";
import { Message, MessageList, QuestionSet, Receipt, Sections, answerValues, type QuestionSetQuestion } from "@tattva/ui";

const questions: QuestionSetQuestion[] = [
  { id: "who", label: "Audience", question: "Who is the survey for?", recommended: "team", options: [
    { value: "team", label: "My team", description: "Up to 20 people you know" },
    { value: "customers", label: "Customers", description: "People who buy from you" },
  ] },
  { id: "topics", label: "Topics", question: "What should it ask about? Pick any.", multiple: true, recommended: "offsite", options: [
    { value: "offsite", label: "The offsite" }, { value: "tools", label: "Tools we use" }, { value: "workload", label: "Workload" },
  ] },
];

export function App() {
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [sent, setSent] = useState(false);
  return (
    <main className="mx-auto w-full max-w-3xl p-4 md:p-8">
      <MessageList label="Conversation">
        <Message role="user">Make me a quick survey.</Message>
        <Message role="assistant">
          {!sent ? (
            <QuestionSet title="Two quick questions" questions={questions} answers={answers}
              onAnswer={(id, v) => setAnswers((a) => ({ ...a, [id]: v }))} allowAgentDecides review
              onUseDefaults={() => { setAnswers({ who: "team", topics: "offsite" }); setSent(true); }}
              onSubmit={() => setSent(true)} submitLabel="Make the survey" />
          ) : (
            <div className="grid gap-3">
              <Receipt title="Answered 2 questions" meta="Just now">
                <p className="m-0 text-body leading-5">For {answers.who === "customers" ? "customers" : "your team"}, about {answerValues(answers.topics).join(", ") || "the offsite"}.</p>
              </Receipt>
              <Sections sections={[
                { id: "q", title: "The questions", meta: "5 questions", content: "1. How useful was the offsite, from 1 to 5? 2. What should we keep? 3. What should we change? 4. Which day worked best? 5. Anything else?" },
                { id: "send", title: "How to send it", content: "Share the link in your team chat. Answers stay anonymous." },
              ]} />
            </div>
          )}
        </Message>
      </MessageList>
    </main>
  );
}
